import json
from pathlib import Path
root=Path.home()/'dojo-data/laptop'
rows=[]
for d in root.iterdir():
 if d.is_dir() and (d.name.startswith('store_laptop_and_headphones-') or d.name.startswith('store_laptop_and_headphones_random-')):
  for p in d.glob('*_episodes.jsonl'):
   for l in p.read_text().splitlines():
    r=json.loads(l); r['run_dir']=d.name; rows.append(r)
print(json.dumps({'manifest':json.loads((root/'panel-manifest.json').read_text()),'rows':rows,'admissions':{p.name:p.read_text() for p in (root/'logs').glob('*.admission')},'progress':(root/'panel-progress.jsonl').read_text() if (root/'panel-progress.jsonl').exists() else ''}))
